/**
 * Agent distribution and installation type definitions
 */

/**
 * Where the agent is distributed from
 */
type DistributionSource =
  | 'github-release' // GitHub releases page
  | 'npm-registry' // NPM package registry
  | 'custom-installer' // Custom installation script/tool
  | 'homebrew' // Homebrew package manager
  | 'direct-download'; // Direct URL download

/**
 * The type of artifact being distributed
 */
type ArtifactType =
  | 'native-binary' // Compiled executable (e.g., Go, Rust binaries)
  | 'node-module-esm' // Node.js ESM module (.mjs)
  | 'node-module-cjs' // Node.js CommonJS module (.js)
  | 'python-package' // Python package
  | 'shell-script'; // Shell script

/**
 * Runtime requirements for the agent
 */
type RuntimeRequirement = 'node' | 'python' | 'deno' | 'bun' | 'none';

/**
 * Complete installation information
 */
export interface InstallationInfo {
  source: DistributionSource;
  artifactType: ArtifactType;
  runtime: RuntimeRequirement;

  // Source-specific information
  githubRepo?: string; // For github-release
  npmPackage?: string; // For npm-registry
  brewFormula?: string; // For homebrew
  downloadUrl?: string; // For direct-download
  installerUrl?: string; // For custom-installer

  // Binary/executable information
  binaryName?: string; // Name of the executable/command (e.g., 'opencode', 'gemini-principle')
  commandName?: string; // Name of the command users will run (e.g., 'principal-gemini', 'principal-opencode')
  assetName?: string; // Name of the asset to download (e.g., 'gemini.mjs', 'opencode')

  // Additional metadata
  requiresWrapper?: boolean; // If a wrapper script is needed
  platformSpecific?: boolean; // If different artifacts per platform
}

/**
 * Helper to determine if an agent needs Node.js
 */
export function requiresNodeJs(info: InstallationInfo): boolean {
  return (
    info.runtime === 'node' ||
    info.artifactType === 'node-module-esm' ||
    info.artifactType === 'node-module-cjs'
  );
}

/**
 * Helper to determine if an agent is distributed as a binary
 */
export function isNativeBinary(info: InstallationInfo): boolean {
  return info.artifactType === 'native-binary';
}
